// Sierpinski Voxels - color only, ANIMATED. Runs INSIDE shadeSurface().
// Pascal's pyramid modulo 2: a voxel (x, y, z) belongs to the Sierpinski
// tetrahedron when x, y and z share no bit (no carry when adding them). Every
// other voxel sits in a hole whose size is the highest shared bit, so the holes
// come in octaves -- 1, 2, 4, 8... voxels. The surface shows where it cuts the
// fractal; holes are colored by size and a brightness wave runs through the scales.
// No displacement: one evaluation per pixel. Integer bit operations (GLSL 4.5).
// In scope: pModel, t. Dock colors: u_col1 = the tetrahedron, u_col2 = big holes.

float CELLS = 24.0 * max(E, 0.05);   // slider E   // voxels per unit        [8 .. 64]
float WAVE  = 0.5 * F;               // slider F   // speed of the wave      [0 .. 2]
const int BITS = 4;                  // repeats every 2^BITS voxels          [3 .. 6]

int   MASK = (1 << BITS) - 1;
vec3  vp = pModel * CELLS;
ivec3 ic = ivec3(floor(vp)) & MASK;
vec3  fp = fract(vp);

int carry = (ic.x & ic.y) | (ic.y & ic.z) | (ic.z & ic.x);
int lvl   = findMSB(carry);          // -1 on the tetrahedron, 0..BITS-1 in a hole

vec3 col;
if (lvl < 0) {
    // the tetrahedron itself, with a thin bevel at the voxel faces
    vec3 e3 = min(fp, 1.0 - fp);
    float gridD = min(e3.x, min(e3.y, e3.z));
    col = ubuf.u_col1 * (0.8 + 0.2 * smoothstep(0.0, 0.12, gridD));
} else {
    float size = float(lvl) / float(BITS - 1);   // 0 = smallest holes, 1 = biggest
    vec3 pal = 0.5 + 0.5 * cos(6.2832 * (0.55 * size + vec3(0.0, 0.33, 0.67)));
    col = mix(ubuf.u_col1 * 0.6, ubuf.u_col2, size);
    col = mix(col, pal * mix(ubuf.u_col1, vec3(1.0), 0.3), 0.45);
    // brightness wave running from the small holes to the big ones
    col *= 0.65 + 0.55 * (0.5 + 0.5 * sin(1.4 * float(lvl) - 2.0 * WAVE * t));
}

textureCol = col;
